(async () => {
  await new Promise(r => setTimeout(r, 3000));
  return JSON.stringify({
    url: location.href,
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,900),
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).slice(0,15),
    inputs: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>({id:i.id,t:i.type,v:(i.value||'').slice(0,40)})).slice(0,10),
    links: Array.from(document.querySelectorAll('a')).filter(a=>a.offsetParent!==null).map(a=>(a.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).slice(0,15)
  });
})()
